    // For digit d itself, only lengths 1..=k.
    //
    // Presses per boring number = length
    // Count all previous digits' boring numbers:
    // Total presses for digits < d = (d-1) * sum_{l=1 to 4} l = (d-1) * 10
    // For digit d, presses for lengths 1..=k = k(k+1)/2

    let presses_for_prev_digits = (d - 1) * 10; // sum of 1+2+3+4 = 10
    let presses_for_current_digit = k * (k + 1) / 2;

    (presses_for_prev_digits + presses_for_current_digit)
